module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

function [7:0] mux2X1;
    input [7:0] a;
    input sel;
    begin
        mux2X1 = sel ? {a[6:0], 1'b0} : a;
    end
endfunction

reg [7:0] temp;
always @(*) begin
    temp = in;

    temp = mux2X1(temp, ctrl[2]);

    temp = mux2X1(temp, ctrl[1]);

    temp = mux2X1(temp, ctrl[0]);
end

assign out = temp;
endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
